-- Reviewed full-details projection. Attachment contents and authentication fields never imported.
-- Related collections contain at most 50 records and expose truncado when a 51st exists.
CREATE OR REPLACE VIEW chatbot.v_office_details WITH (security_barrier=true) AS
SELECT p.id AS office_id, p.departamento::text AS department,
jsonb_build_object('tabla', 'sucursales', 'campos', to_jsonb(p), 'omitidos', '[]'::jsonb) || jsonb_build_object('relaciones', jsonb_build_object('usuarios', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT jsonb_build_object('tabla', 'users', 'campos', to_jsonb(r), 'omitidos', '["email_verified_at", "password", "remember_token"]'::jsonb) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."users" r WHERE r.sucursal_id=p.id ORDER BY r.id LIMIT 51) x))) AS details
FROM chatbot_details_source.sucursales p WHERE current_setting('chatbot.access_scope', true) = 'global_internal' AND current_setting('chatbot.personal_access', true) = 'allowed';
CREATE OR REPLACE VIEW chatbot.v_tracking_details WITH (security_barrier=true) AS
SELECT 'certi'::text AS source, p.codigo::text AS tracking_code, jsonb_build_object('tabla', 'paquetes_certi', 'campos', to_jsonb(p), 'omitidos', '["imagen"]'::jsonb) || jsonb_build_object('relaciones', jsonb_build_object('bitacoras', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT jsonb_build_object('tabla', 'bitacoras', 'campos', to_jsonb(r), 'omitidos', '["imagen_factura", "qr_url", "qr_texto", "qr_datos"]'::jsonb) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."bitacoras" r WHERE r."paquetes_certi_id"=p.id ORDER BY r.id LIMIT 51) x), 'cartero', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT jsonb_build_object('tabla', 'cartero', 'campos', to_jsonb(r), 'omitidos', '["foto", "imagen", "imagen_devolucion"]'::jsonb) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."cartero" r WHERE r."id_paquetes_certi"=p.id ORDER BY r.id LIMIT 51) x), 'malencaminados', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT jsonb_build_object('tabla', 'malencaminados', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."malencaminados" r WHERE r."paquetes_certi_id"=p.id ORDER BY r.id LIMIT 51) x), 'fk_estado', (SELECT jsonb_build_object('tabla', 'estados', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) FROM chatbot_details_source."estados" r WHERE r."id"=p."fk_estado" LIMIT 1), 'fk_ventanilla', (SELECT jsonb_build_object('tabla', 'ventanilla', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) FROM chatbot_details_source."ventanilla" r WHERE r."id"=p."fk_ventanilla" LIMIT 1), 'servicio_id', (SELECT jsonb_build_object('tabla', 'servicio', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) FROM chatbot_details_source."servicio" r WHERE r."id"=p."servicio_id" LIMIT 1), 'eventos_por_codigo', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT (jsonb_build_object('tabla', 'eventos_certi', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) || jsonb_build_object('evento', (SELECT to_jsonb(e) FROM chatbot_details_source.eventos e WHERE e.id=r.evento_id LIMIT 1), 'usuario', (SELECT to_jsonb(u) FROM chatbot_details_source.users u WHERE u.id=r.user_id LIMIT 1))) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."eventos_certi" r WHERE r.codigo=p.codigo ORDER BY r.id LIMIT 51) x), 'asociacion_eventos', to_jsonb('Coincidencia por codigo; origen no declara FK al paquete'::text))) AS details FROM chatbot_details_source."paquetes_certi" p WHERE current_setting('chatbot.access_scope', true) = 'global_internal' AND current_setting('chatbot.personal_access', true) = 'allowed'
UNION ALL
SELECT 'ordi'::text AS source, p.codigo::text AS tracking_code, jsonb_build_object('tabla', 'paquetes_ordi', 'campos', to_jsonb(p), 'omitidos', '["imagen"]'::jsonb) || jsonb_build_object('relaciones', jsonb_build_object('bitacoras', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT jsonb_build_object('tabla', 'bitacoras', 'campos', to_jsonb(r), 'omitidos', '["imagen_factura", "qr_url", "qr_texto", "qr_datos"]'::jsonb) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."bitacoras" r WHERE r."paquetes_ordi_id"=p.id ORDER BY r.id LIMIT 51) x), 'cartero', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT jsonb_build_object('tabla', 'cartero', 'campos', to_jsonb(r), 'omitidos', '["foto", "imagen", "imagen_devolucion"]'::jsonb) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."cartero" r WHERE r."id_paquetes_ordi"=p.id ORDER BY r.id LIMIT 51) x), 'malencaminados', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT jsonb_build_object('tabla', 'malencaminados', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."malencaminados" r WHERE r."paquetes_ordi_id"=p.id ORDER BY r.id LIMIT 51) x), 'fk_estado', (SELECT jsonb_build_object('tabla', 'estados', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) FROM chatbot_details_source."estados" r WHERE r."id"=p."fk_estado" LIMIT 1), 'fk_ventanilla', (SELECT jsonb_build_object('tabla', 'ventanilla', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) FROM chatbot_details_source."ventanilla" r WHERE r."id"=p."fk_ventanilla" LIMIT 1), 'servicio_id', (SELECT jsonb_build_object('tabla', 'servicio', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) FROM chatbot_details_source."servicio" r WHERE r."id"=p."servicio_id" LIMIT 1), 'eventos_por_codigo', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT (jsonb_build_object('tabla', 'eventos_ordi', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) || jsonb_build_object('evento', (SELECT to_jsonb(e) FROM chatbot_details_source.eventos e WHERE e.id=r.evento_id LIMIT 1), 'usuario', (SELECT to_jsonb(u) FROM chatbot_details_source.users u WHERE u.id=r.user_id LIMIT 1))) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."eventos_ordi" r WHERE r.codigo=p.codigo ORDER BY r.id LIMIT 51) x), 'asociacion_eventos', to_jsonb('Coincidencia por codigo; origen no declara FK al paquete'::text))) AS details FROM chatbot_details_source."paquetes_ordi" p WHERE current_setting('chatbot.access_scope', true) = 'global_internal' AND current_setting('chatbot.personal_access', true) = 'allowed'
