_details_source."estados" r WHERE r."id"=p."estados_id" LIMIT 1), 'tarifa_contrato_id', (SELECT jsonb_build_object('tabla', 'tarifa_contrato', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) FROM chatbot_details_source."tarifa_contrato" r WHERE r."id"=p."tarifa_contrato_id" LIMIT 1), 'user_id', (SELECT jsonb_build_object('tabla', 'users', 'campos', to_jsonb(r), 'omitidos', '["email_verified_at", "password", "remember_token"]'::jsonb) FROM chatbot_details_source."users" r WHERE r."id"=p."user_id" LIMIT 1), 'eventos_por_codigo', (SELECT jsonb_build_object('registros', COALESCE(jsonb_agg(x.record ORDER BY x.id) FILTER (WHERE x.rn<=50), '[]'::jsonb), 'truncado', count(*)>50, 'limite', 50) FROM (SELECT (jsonb_build_object('tabla', 'eventos_contrato', 'campos', to_jsonb(r), 'omitidos', '[]'::jsonb) || jsonb_build_object('evento', (SELECT to_jsonb(e) FROM chatbot_details_source.eventos e WHERE e.id=r.evento_id LIMIT 1), 'usuario', (SELECT to_jsonb(u) FROM chatbot_details_source.users u WHERE u.id=r.user_id LIMIT 1))) AS record, r.id, row_number() OVER (ORDER BY r.id) AS rn FROM chatbot_details_source."eventos_contrato" r WHERE r.codigo=p.codigo ORDER BY r.id LIMIT 51) x), 'asociacion_eventos', to_jsonb('Coincidencia por codigo; origen no declara FK al paquete'::text))) AS details FROM chatbot_details_source."paquetes_contrato" p WHERE current_setting('chatbot.access_scope', true) = 'global_internal' AND current_setting('chatbot.personal_access', true) = 'allowed'
